from decimal import Decimal, ROUND_DOWN
product = {"sku": "TEE-BLK-M", "price_krw": 39000, "size": "M"}

def to_jp_market(p, krw_per_jpy):
    jpy = (Decimal(p["price_krw"]) / Decimal(krw_per_jpy)).quantize(Decimal("1"), ROUND_DOWN)
    return {"goodsCode": p["sku"], "price": int(jpy), "currency": "JPY", "sizeName": p["size"]}

def to_cn_market(p, krw_per_cny):
    cny = (Decimal(p["price_krw"]) / Decimal(krw_per_cny)).quantize(Decimal("0.01"), ROUND_DOWN)
    return {"outer_id": p["sku"], "price": str(cny), "props": {"尺码": p["size"]}}

print(to_jp_market(product, "9.30"))
print(to_cn_market(product, "195.5"))
# {'goodsCode': 'TEE-BLK-M', 'price': 4193, 'currency': 'JPY', 'sizeName': 'M'}
# {'outer_id': 'TEE-BLK-M', 'price': '199.48', 'props': {'尺码': 'M'}}

import random
random.seed(7)
market_stock, seen, calls = {}, {}, 0

def market_add_stock(sku, qty, key):
    global calls
    calls += 1
    if key is not None and key in seen:
        return seen[key]              # 같은 열쇠 → 다시 처리하지 않음
    market_stock[sku] = market_stock.get(sku, 0) + qty
    if key is not None:
        seen[key] = "ok"
    if calls % 3 != 0:
        raise TimeoutError("응답 지연")
    return "ok"

def send(sku, qty, key, tries=5, base=0.2, cap=5.0):
    waits = []
    for i in range(tries):
        try:
            return market_add_stock(sku, qty, key), waits
        except TimeoutError:
            waits.append(round(random.uniform(0, min(cap, base * 2 ** i)), 2))
    raise RuntimeError("포기 -> 대사 대기열로")

print("열쇠 없이:", send("TEE-BLK-M", 5, None), market_stock)
market_stock.clear(); seen.clear(); calls = 0
print("열쇠 있게:", send("TEE-BLK-M", 5, "stock:TEE-BLK-M:v42"), market_stock)
# 열쇠 없이: ('ok', [0.06, 0.06]) {'TEE-BLK-M': 15}
# 열쇠 있게: ('ok', [0.13]) {'TEE-BLK-M': 5}

rate, burst = 2.0, 5
tokens, t, sent, queue = float(burst), 0.0, [], list(range(1, 11))
while queue:
    if tokens >= 1:
        tokens -= 1; sent.append((queue.pop(0), round(t, 1)))
    else:
        t += 0.1; tokens = min(burst, tokens + rate * 0.1)
print(sent)
